<script setup lang="ts">
import { onMounted, reactive, ref } from 'vue'
import { listarSaldos, obtenerFicha, urlExportarSaldos, urlKardex } from '../services/saldos'
import type { CatalogoSaldo, FichaItem, SaldoItem } from '../interfaces/saldos.interface'
const rows=ref<SaldoItem[]>([]),almacenes=ref<CatalogoSaldo[]>([]),periodos=ref<CatalogoSaldo[]>([]),tipos=ref<Record<string,string>>({}),summary=reactive({items:0,unidades:0,valor_total:0,sin_stock:0}),page=ref(1),lastPage=ref(1),total=ref(0),loading=ref(false),error=ref(''),detail=ref<FichaItem|null>(null)
const filters=reactive({almacen:'',tipo:'',periodo:'',item:''})
async function load(next=1){page.value=next;loading.value=true;error.value='';try{const r=await listarSaldos({...filters,page:next});rows.value=r.data;almacenes.value=r.almacenes;periodos.value=r.periodos;tipos.value=r.tipos;total.value=r.total;lastPage.value=r.last_page;Object.assign(summary,r.resumen);if(!filters.almacen&&r.almacen_default_id)filters.almacen=String(r.almacen_default_id);if(!filters.periodo&&r.periodos[0])filters.periodo=String(r.periodos[0].id)}catch(e){error.value=message(e)}finally{loading.value=false}}
function clear(){Object.assign(filters,{tipo:'',item:''});load(1)}
async function show(row:SaldoItem){if(!filters.almacen||!filters.periodo){error.value='Seleccione almacén y periodo.';return}try{detail.value=await obtenerFicha(row.item_id,filters.almacen,filters.periodo)}catch(e){error.value=message(e)}}
function exportUrl(format:'xlsx'|'pdf'){return urlExportarSaldos(format,{...filters})}
const number=(v=0)=>new Intl.NumberFormat('es-PE',{minimumFractionDigits:2,maximumFractionDigits:2}).format(v),money=(v=0)=>new Intl.NumberFormat('es-PE',{style:'currency',currency:'PEN'}).format(v),message=(e:unknown)=>e instanceof Error?e.message:'No se pudieron consultar los saldos.'
onMounted(()=>load())
</script>
<template><div class="page"><nav><RouterLink to="/inicio">Inicio</RouterLink> / Administración / Almacén / Saldos</nav><header class="hero"><div class="mark">SL</div><div><small>MIA · ALMACÉN</small><h1>Saldos de almacén</h1><p>Consulta existencias y valorización por periodo.</p></div><div class="exports"><a :href="exportUrl('xlsx')" target="_blank">Excel</a><a class="pdf" :href="exportUrl('pdf')" target="_blank">PDF</a></div></header><p v-if="error" class="flash">{{error}}</p>
<section class="metrics"><article><small>ÍTEMS</small><b>{{summary.items}}</b></article><article><small>UNIDADES EN STOCK</small><b>{{number(summary.unidades)}}</b></article><article><small>VALOR DE INVENTARIO</small><b>{{money(summary.valor_total)}}</b></article><article class="danger"><small>SIN STOCK</small><b>{{summary.sin_stock}}</b></article></section>
<section class="filters"><label>Almacén<select v-model="filters.almacen"><option value="">Seleccione</option><option v-for="x in almacenes" :key="x.id" :value="x.id">{{x.nombre}}</option></select></label><label>Tipo de ítem<select v-model="filters.tipo"><option value="">Todos</option><option v-for="(name,id) in tipos" :key="id" :value="id">{{name}}</option></select></label><label>Periodo<select v-model="filters.periodo"><option value="">Seleccione</option><option v-for="x in periodos" :key="x.id" :value="x.id">{{x.nombre}}</option></select></label><label class="wide">Descripción<input v-model.trim="filters.item" placeholder="Descripción del ítem" @keyup.enter="load(1)"></label><button @click="load(1)">Buscar</button><button class="soft" @click="clear">Limpiar</button></section>
<section class="table-card"><header><div><small>INVENTARIO</small><h2>Listado de ítems</h2></div><b>{{total}} resultados</b></header><div v-if="loading" class="empty">Consultando saldos…</div><div v-else-if="!rows.length" class="empty">No se encontraron saldos para los filtros seleccionados.</div><div v-else class="scroll"><table><thead><tr><th>Ítem</th><th>Descripción</th><th>Unidad</th><th class="right">Stock</th><th class="right">Precio medio</th><th class="right">Valor</th><th>Tipo</th><th>Último movimiento</th><th>Fecha</th><th></th></tr></thead><tbody><tr v-for="row in rows" :key="row.item_id" :class="{emptyStock:row.stock<=0}"><td>#{{row.item_id}}</td><td><b>{{row.descripcion}}</b></td><td>{{row.unidad}}</td><td class="right"><span v-if="row.stock<=0" class="no-stock">SIN STOCK</span><b v-else>{{number(row.stock)}}</b></td><td class="right">{{money(row.precio_medio)}}</td><td class="right">{{money(row.valor_total)}}</td><td><span class="type" :class="row.tipo_codigo">{{row.tipo}}</span></td><td><span class="movement" :class="row.ultimo_mov.toLowerCase()">{{row.ultimo_mov}}</span></td><td>{{row.fecha}}</td><td class="actions"><button @click="show(row)">Ficha</button><a v-if="filters.almacen&&filters.periodo" :href="urlKardex(row.item_id,filters.almacen,filters.periodo)" target="_blank">Kardex</a></td></tr></tbody></table></div><footer v-if="lastPage>1"><button :disabled="page<=1" @click="load(page-1)">Anterior</button><span>{{page}} / {{lastPage}}</span><button :disabled="page>=lastPage" @click="load(page+1)">Siguiente</button></footer></section>
<div v-if="detail" class="backdrop" @mousedown.self="detail=null"><section class="dialog"><header><div><small>FICHA DEL ÍTEM</small><h2>{{detail.descripcion}}</h2><p>{{detail.codigo||`Ítem #${detail.item_id}`}} · {{detail.tipo}}</p></div><button @click="detail=null">×</button></header><div class="info"><div><small>ALMACÉN</small><b>{{detail.almacen}}</b></div><div><small>UNIDAD</small><b>{{detail.unidad}}</b></div><div><small>UBICACIÓN</small><b>{{detail.ubicacion||'No registrada'}}</b></div><div><small>CONSUMO MEDIO</small><b>{{number(detail.consumo_medio)}}</b></div></div><div class="balance"><div><small>Stock actual</small><b>{{number(detail.stock)}}</b></div><div><small>Precio medio</small><b>{{money(detail.precio_medio)}}</b></div><div><small>Valor total</small><b>{{money(detail.valor_total)}}</b></div></div><p>Rango de inventario: mínimo <b>{{number(detail.stock_minimo)}}</b> / máximo <b>{{number(detail.stock_maximo)}}</b></p><footer><button @click="detail=null">Cerrar</button></footer></section></div></div></template>
<style scoped>
